const diasAGenerar = configuracion.dias || 7;

// Normaliza KM: saca puntos, comas, espacios y cualquier char no numérico
function normalizarKM(valor) {
  if (valor === null || valor === undefined) return NaN;
  const limpio = valor.toString().replace(/[^\d]/g, '');
  return limpio ? parseInt(limpio, 10) : NaN;
}

// Normaliza nombre de modelo: minúsculas, sin espacios, guiones, guion bajo ni tildes
function normalizarModelo(valor) {
  return (valor || '')
    .toString()
    .trim()
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '') // saca tildes
    .replace(/[\s\-_]/g, '');
}

const kmSolicitado = normalizarKM(configuracion.km);
const modeloSolicitado = normalizarModelo(configuracion.modelo);

// ======================================================
// OBTENER DURACIÓN SEGÚN MODELO + KM
// ======================================================
let duracionTurnoMinutos = 60; // fallback
let debugInfo = { filaEncontrada: false, columnaEncontrada: false, valorCelda: null };

if (sheetRows.length > 0) {
  const filaKM = sheetRows.find(r => {
    const kmFila = normalizarKM(r.KM ?? r.Km ?? r.km);
    return kmFila === kmSolicitado;
  });

  if (filaKM) {
    debugInfo.filaEncontrada = true;
    const columnas = Object.keys(filaKM);

    const columnaModelo = columnas.find(
      col => normalizarModelo(col) === modeloSolicitado
    );

    if (columnaModelo && filaKM[columnaModelo]) {
      debugInfo.columnaEncontrada = true;
      debugInfo.valorCelda = filaKM[columnaModelo];

      const match = /^(\d+):(\d{2}):(\d{2})$/.exec(filaKM[columnaModelo].toString().trim());
      if (match) {
        duracionTurnoMinutos =
          parseInt(match[1], 10) * 60 +
          parseInt(match[2], 10);
      }
    }
  }
}

// Log para depurar directamente en el panel de ejecución de n8n
console.log('kmSolicitado:', kmSolicitado, '| modeloSolicitado:', modeloSolicitado, '| debugInfo:', debugInfo);

// ======================================================
// FUNCIONES DE TIEMPO
// ======================================================
function convertirAMinutos(hora) {
  const [h, m] = hora.split(':').map(Number);
  return h * 60 + m;
}

function convertirDesdeMinutos(min) {
  // Contempla por si el cálculo cruza medianoche (min negativo o > 1440)
  const minNormalizado = ((min % 1440) + 1440) % 1440;
  const h = Math.floor(minNormalizado / 60);
  const m = minNormalizado % 60;
  return `${h.toString().padStart(2,'0')}:${m.toString().padStart(2,'0')}`;
}

function generarSlots(inicio, fin, duracion) {
  const slots = [];
  const ini = convertirAMinutos(inicio);
  const finM = convertirAMinutos(fin);

  for (let m = ini; m + duracion <= finM; m += duracion) {
    slots.push({
      inicio: convertirDesdeMinutos(m),
      fin: convertirDesdeMinutos(m + duracion)
    });
  }
  return slots;
}

function hayConflicto(inicio, fin, ocupados) {
  const ini = convertirAMinutos(inicio);
  const finM = convertirAMinutos(fin);

  return ocupados.some(t => {
    const oIni = convertirAMinutos(t.inicio);
    const oFin = convertirAMinutos(t.final);
    return ini < oFin && finM > oIni;
  });
}

// ======================================================
// FECHAS LABORABLES
// ======================================================
function generarFechasProximosDias(cantidad) {
  const feriados = [
    '2025-01-01','2025-03-03','2025-03-04','2025-03-24',
    '2025-04-18','2025-04-02','2025-05-01','2025-05-25',
    '2025-06-20','2025-07-09','2025-08-17','2025-10-12',
    '2025-11-24','2025-12-08','2025-12-25'
  ];

  const hoy = new Date();
  const fechas = [];
  let i = 1;

  while (fechas.length < cantidad) {
    const f = new Date(hoy);
    f.setDate(hoy.getDate() + i);

    const iso = f.toISOString().split('T')[0];
    const dow = f.getDay();

    if (dow >= 1 && dow <= 5 && !feriados.includes(iso)) {
      fechas.push(iso);
    }
    i++;
  }
  return fechas;
}

function formatoCorto(fechaISO) {
  const fecha = new Date(fechaISO);
  const dias = ["domingo","lunes","martes","miércoles","jueves","viernes","sábado"];
  const diaNombre = dias[fecha.getDay()];
  const dia = String(fecha.getDate()).padStart(2,'0');
  const mes = String(fecha.getMonth()+1).padStart(2,'0');
  const anio = fecha.getFullYear();
  return `${diaNombre.charAt(0).toUpperCase()+diaNombre.slice(1)} ${dia}/${mes}/${anio}`;
}

