          finalizacionLavado,
          fechaHora: `${dia} ${slot.inicio}-${slot.fin}`,
          fecha_formato_corto: formatoCorto(dia)
        });
      }
    }
  }

  resultado[dia].sort(
    (a,b) => convertirAMinutos(a.inicio) - convertirAMinutos(b.inicio)
  );
